// Layer 1: Schema Normalization & Payload Parser
const item = $input.first().json;
return [{
  json: {
    invoice_id: item.invoice_id || ('INV-' + Date.now().toString().slice(-4)),
    supplier_name: item.supplier_name || 'Unknown Supplier',
    supplier_gstin: (item.supplier_gstin || '').toUpperCase().trim(),
    invoice_number: item.invoice_number || 'INV-000',
    invoice_date: item.invoice_date || new Date().toISOString().split('T')[0],
    subtotal: parseFloat(item.subtotal || 0),
    tax_amount: parseFloat(item.tax_amount || 0),
    total_amount: parseFloat(item.total_amount || 0),
    source: item.source || 'email'
  }
}];

// Layer 2: Deterministic Rule Guardrails (No AI)
const inv = $input.first().json;
const violations = [];

// 1. GSTIN Regex Check (Indian standard 15-char)
const gstinRegex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
if (!inv.supplier_gstin || !gstinRegex.test(inv.supplier_gstin)) {
  violations.push('Invalid GSTIN format: ' + inv.supplier_gstin);
}

// 2. Tax Arithmetic Check
const calculatedTotal = Math.round((inv.subtotal + inv.tax_amount) * 100) / 100;
if (Math.abs(calculatedTotal - inv.total_amount) > 0.05) {
  violations.push(`Tax arithmetic mismatch: Subtotal (${inv.subtotal}) + Tax (${inv.tax_amount}) != Total (${inv.total_amount})`);
}

// 3. GST Slab check (0, 5, 12, 18, 28%)
if (inv.subtotal > 0) {
  const rate = Math.round((inv.tax_amount / inv.subtotal) * 1000) / 1000;
  const validSlabs = [0, 0.05, 0.12, 0.18, 0.28];
  const matchesSlab = validSlabs.some(s => Math.abs(rate - s) < 0.008);
  if (!matchesSlab) {
    violations.push(`Tax rate ${(rate*100).toFixed(1)}% does not match standard GST slabs (5%, 12%, 18%, 28%)`);
  }
}

const passed = violations.length === 0;
return [{
  json: {
    ...inv,
    guardrails_passed: passed,
    violations: violations,
    blocked_layer: passed ? null : 'LAYER_2_GUARDRAILS'
  }
}];

// Layer 3: AI Reconciliation Agent Simulation / Execution
// In production n8n, this is the LangChain AI Agent node with tool connections
const inv = $input.first().json;

// Call local Python microservice or embedded tool logic
return [{
  json: {
    ...inv,
    agent_run_id: 'AGENT-' + Date.now(),
    confidence: inv.total_amount > 40000 ? 'MEDIUM' : 'HIGH',
    decision: inv.total_amount > 40000 ? 'COMBINED_PAYMENT_SUGGESTED' : 'AUTO_RESOLVE_PAID',
    matched_bank_ref: 'UTR-CNB0903001',
    reasoning_trace: [
      'Step 1: Ingested invoice ' + inv.invoice_number,
      'Step 2: Guardrails passed (GSTIN & Tax validated)',
      'Step 3: Searched bank rows with tolerance',
      'Step 4: Matched supplier alias and settled transaction'
    ]
  }
}];

